// Function for MATLAB Function: '<S176>/VariableHorizonOptimizer'
int32_T proc_control::proc_control_xpotrf(int32_T n, real_T b_A_data[], int32_T
  lda)
{
  int32_T info;
  int32_T j;
  boolean_T exitg1;
  info = 0;
  j = 0;
  exitg1 = false;
  while ((!exitg1) && (j <= static_cast<uint8_T>(n) - 1)) {
    real_T c;
    real_T ssq;
    int32_T b_k;
    int32_T idxAjj;
    idxAjj = j * lda + j;
    ssq = 0.0;
    if (j >= 1) {
      for (b_k = 0; b_k < j; b_k++) {
        c = b_A_data[b_k * lda + j];
        ssq += c * c;
      }
    }

    ssq = b_A_data[idxAjj] - ssq;
    if (ssq > 0.0) {
      ssq = std::sqrt(ssq);
      b_A_data[idxAjj] = ssq;
      if (j + 1 < n) {
        int32_T b_iy;
        int32_T ix;
        b_iy = (n - j) - 1;
        if ((b_iy != 0) && (j != 0)) {
          int32_T b;
          ix = j;
          b = ((j - 1) * lda + j) + 2;
          for (b_k = j + 2; lda < 0 ? b_k >= b : b_k <= b; b_k += lda) {
            int32_T d;
            c = -b_A_data[ix];
            d = (b_k + b_iy) - 1;
            for (int32_T b_ix{b_k}; b_ix <= d; b_ix++) {
              int32_T tmp_0;
              tmp_0 = ((idxAjj + b_ix) - b_k) + 1;
              b_A_data[tmp_0] += b_A_data[b_ix - 1] * c;
            }

            ix += lda;
          }
        }

        ssq = 1.0 / ssq;
        b_k = idxAjj + b_iy;
        ix = ((((b_k - idxAjj) / 2) << 1) + idxAjj) + 2;
        b_iy = ix - 2;
        for (int32_T b_ix{idxAjj + 2}; b_ix <= b_iy; b_ix += 2) {
          __m128d tmp;
          tmp = _mm_loadu_pd(&b_A_data[b_ix - 1]);
          _mm_storeu_pd(&b_A_data[b_ix - 1], _mm_mul_pd(tmp, _mm_set1_pd(ssq)));
        }

        for (int32_T b_ix{ix}; b_ix <= b_k + 1; b_ix++) {
          b_A_data[b_ix - 1] *= ssq;
        }
      }

      j++;
    } else {
      b_A_data[idxAjj] = ssq;
      info = j + 1;
      exitg1 = true;
    }
  }

  return info;
}

