           case 5:
            maxConstr_new = solution->xstar.data[objective->nvar - 1] *
              objective->gammaScalar;
            break;

           case 3:
            proc_control_linearForm_(objective->hasLinear, objective->nvar,
              memspace->workspace_float.data, H, f_data, solution->xstar.data);
