// Function for MATLAB Function: '<S217>/NLMPC'
real_T proc_control::proc_con_maxConstraintViolation(const
  s_PAtG1CW05sRYOWrqzwRQyC_proc_T *obj, const real_T x_data[])
{
  real_T v;
  int32_T b;
  int32_T idx;
  if (obj->probType == 2) {
    proc_control_B.b_obj = *obj;
    v = maxConstraintViolation_AMats_re(&proc_control_B.b_obj, x_data);
  } else {
    proc_control_B.b_obj = *obj;
    v = maxConstraintViolation_AMats_no(&proc_control_B.b_obj, x_data);
  }

  if (obj->sizes[3] > 0) {
    b = static_cast<uint16_T>(obj->sizes[3]);
    for (idx = 0; idx < b; idx++) {
      v = std::fmax(v, -x_data[proc_control_B.b_obj.indexLB.data[idx] - 1] -
                    proc_control_B.b_obj.lb.data[proc_control_B.b_obj.indexLB.data
                    [idx] - 1]);
    }
  }

  if (obj->sizes[4] > 0) {
    b = static_cast<uint16_T>(obj->sizes[4]);
    for (idx = 0; idx < b; idx++) {
      v = std::fmax(v, x_data[proc_control_B.b_obj.indexUB.data[idx] - 1] -
                    proc_control_B.b_obj.ub.data[proc_control_B.b_obj.indexUB.data
                    [idx] - 1]);
    }
  }

  if (obj->sizes[0] > 0) {
    b = static_cast<uint16_T>(obj->sizes[0]);
    for (idx = 0; idx < b; idx++) {
      v = std::fmax(v, std::abs(x_data[proc_control_B.b_obj.indexFixed.data[idx]
        - 1] -
        proc_control_B.b_obj.ub.data[proc_control_B.b_obj.indexFixed.data[idx] -
        1]));
    }
  }

  return v;
}

